    return out


def project_weights(raw):
    # Iterative bounded-simplex projection; always returns a complete 15-asset vector.
    raw = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    free, fixed = set(UNIVERSE), {}
    for _ in range(40):
