import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble (five admitted factors; all directions positive).
FACTOR_WEIGHTS = {"clv": .28, "peer": .22, "momentum": .22, "reversal": .14, "intraday": .14}
MIN_WEIGHT, MAX_WEIGHT = .015, .16
REBALANCE_DAYS = 10
last_decision = None
previous_score = None


def rank_cross_section(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n if n > 1 else .5
    return out


def project_weights(raw):
    """Project positive scores to a bounded simplex; preserves all 15 assets."""
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    fixed, free = {}, set(UNIVERSE)
    for _ in range(40):
        scale = (1.0 - sum(fixed.values())) / max(sum(w[s] for s in free), 1e-12)
        low = [s for s in free if w[s] * scale < MIN_WEIGHT]
        high = [s for s in free if w[s] * scale > MAX_WEIGHT]
        if not low and not high:
            fixed.update({s: w[s] * scale for s in free})
            free.clear()
            break
        chosen, bound = (low, MIN_WEIGHT) if low else (high, MAX_WEIGHT)
        for s in chosen:
            fixed[s] = bound
            free.remove(s)
    if free:
        rem = max(1.0 - sum(fixed.values()), 0.0)
        den = max(sum(w[s] for s in free), 1e-12)
        fixed.update({s: rem * w[s] / den for s in free})
    total = sum(fixed.values())
    return {s: fixed.get(s, 0.0) / max(total, 1e-12) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision, previous_score
    series = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], float)
        o = np.asarray(df["open"], float)
        h = np.asarray(df["high"], float)
        l = np.asarray(df["low"], float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        series[symbol] = (c, o, h, l, r, str(df.iloc[-1]["date"]))
    if len(series) < 12:
        return
    decision_date = max(x[5] for x in series.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision_date) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < REBALANCE_DAYS:
                return
        except Exception:
            return

    clv, peer, reversal, momentum, intraday, invvol = ({}, {}, {}, {}, {}, {})
    for s, (c, o, h, l, r, _) in series.items():
        vol = max(float(np.std(r[-20:])), 0.008)
        candle = (2.0*c - h - l) / np.maximum(h - l, 1e-12)
        # Smooth one-day CLV to reduce noise while retaining its admitted direction.
        clv[s] = float(np.mean(candle[-3:]))
        reversal[s] = float(-np.mean(r[-5:]))
        intraday[s] = float(-np.mean(c[-3:] / np.maximum(o[-3:], 1e-12) - 1.0))
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + .01))
        peer[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        invvol[s] = 1.0 / vol
    med = float(np.median(list(peer.values())))
    peer = {s: v - med for s, v in peer.items()}
    raw_factors = {"clv": clv, "peer": peer, "momentum": momentum,
                   "reversal": reversal, "intraday": intraday}
    ranked = {k: rank_cross_section(v) for k, v in raw_factors.items()}
    score = {s: sum(FACTOR_WEIGHTS[k] * ranked[k][s] for k in FACTOR_WEIGHTS) for s in UNIVERSE}
    # More persistence than the prior 60/40 blend, appropriate for high-risk conditions.
    if previous_score is not None:
        score = {s: .70 * previous_score.get(s, score[s]) + .30 * score[s] for s in UNIVERSE}
    previous_score = dict(score)

    breadth = float(np.mean([c[-1] > c[-21] for c, *_ in series.values()]))
    market_vol = float(np.mean([np.std(x[4][-20:]) for x in series.values()]))
    if breadth < .55 or market_vol > .025:
        # Full investment is retained, with defensive tradable benchmarks as the hedge.
        for s in ("XAU", "US10Y", "CN10Y"):
            if s in score:
                score[s] += .20
        for s in ("BTC", "ETH", "WTI"):
            if s in score:
                score[s] -= .10

    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(score[s], .03) * (.70 + .30 * invvol.get(s, mean_iv) / max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = project_weights(raw)
    avg = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-12)
    forecast = {s: .01 * (score[s] - avg) / sd for s in UNIVERSE}
    try:
        ens = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        ids = [x["factor_id"] for x in ens.get("selected_factors", []) if x.get("factor_id")][:10]
    except Exception:
        ids = []
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_decision = decision_date

if __name__ == "__main__":
    pass"}

