import pandas as pd,numpy as np,glob,os
from scipy.stats import spearmanr
cut=pd.Timestamp('2027-03-24'); assets=[os.path.basename(x)[:-4] for x in glob.glob('../persistent/stock_data/*.csv')]
# independently compute rolling features; align by calendar date without requiring common history
frames=[]
for a in assets:
 d=pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).sort_values('date'); d=d[d.date<=cut].set_index('date'); ret=d.close.pct_change(fill_method=None)
 fast=d.close.pct_change(5,fill_method=None); slow=d.close.pct_change(20,fill_method=None); vol=ret.rolling(20,min_periods=15).std()*np.sqrt(20)
 frames.append(pd.DataFrame({'date':d.index,'asset':a,'fac':((fast-slow)/(vol+1e-8)).clip(-10,10).values,'f1':d.close.pct_change(-1,fill_method=None).values,'f5':d.close.pct_change(-5,fill_method=None).values,'f10':d.close.pct_change(-10,fill_method=None).values}))
x=pd.concat(frames).set_index(['date','asset']).sort_index(); fac=x.fac.unstack();
# forward returns via shifted close, avoiding cross-sectional date loss
vals={h:[] for h in [1,5,10]}; ns={h:[] for h in vals}; ds={h:[] for h in vals}
for dt,g in x.groupby(level=0):
 z=g.droplevel(0); f=z.fac
 for h,col in [(1,'f1'),(5,'f5'),(10,'f10')]:
  q=pd.concat([f,z[col]],axis=1).dropna()
  if len(q)>=8 and q.iloc[:,0].nunique()>1 and q.iloc[:,1].nunique()>1:
   vals[h].append(spearmanr(q.iloc[:,0],q.iloc[:,1]).statistic);ds[h].append(dt);ns[h].append(len(q))
print('assets',len(assets),'dates',len(fac),'period',fac.index.min(),fac.index.max())
for h in vals:
 s=pd.Series(vals[h],index=ds[h]); print('H',h,'dates',len(s),'avgN',round(np.mean(ns[h]),2),'IC %.6f ICIR %.6f hit %.4f'%(s.mean(),s.mean()/s.std(ddof=1),(s>0).mean()))
 if h==1:
  for lo,hi in [('2020','2022-12-31'),('2023','2024-12-31'),('2025','2027-03-24')]:
   q=s[(s.index>=lo)&(s.index<=hi)];print('regime',lo,hi,'IC %.6f n %d'%(q.mean(),len(q)))
print('coverage',x.fac.notna().mean(),'turnover',fac.rank(axis=1,pct=True).diff().abs().mean().mean())
fac.to_csv('scripts/miner_1_20270325_trend_acceleration_signal.csv')

