macro=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).sort_values('date').set_index('date'); mv=macro['close'].pct_change(); vz=(mv-mv.rolling(20,min_periods=10).median()).clip(-.5,.5)
