 # VIX-shock-conditioned volume reversal: contrarian 2d return, normalized by 10d vol, with positive VIX shock increasing its weight.
 rv=r.rolling(10,min_periods=8).std(); base=(-d.close.pct_change(2)/rv).clip(-10,10)
 x=base*(1+0.75* vz.reindex(d.index).fillna(0).clip(lower=0))*(1+0.35*shock.clip(lower=0))
 F[a]=x
 for h in fw: fw[h][a]=d.close.pct_change(h).shift(-h)
fac=pd.DataFrame(F).sort_index(); fac.to_csv('scripts/miner_1_20270325_vix_volume_reversal_signal.csv')
print('assets',len(assets),'rows',len(fac),'period',fac.index.min(),fac.index.max())
for h in fw:
 fwd=pd.DataFrame(fw[h]).reindex(fac.index); vals=[]; ds=[]; ns=[]
