U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P={}
for s in U:
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date'); P[s]=d.close.astype(float)
p=pd.DataFrame(P).sort_index(); r=p.pct_change();
# persistence-adjusted medium momentum: return over 30 sessions weighted by directional hit rate, volatility scaled
hit=(r.rolling(30).mean()/(r.rolling(30).abs().mean()+1e-9)).clip(-1,1)
fac=p.pct_change(30)*hit/(r.rolling(30).std()*np.sqrt(30)+1e-9)
